@startuml

enum PriorityScore {
  High
  Low
}

class Patient {
  + FirstName : string
  + LastName : string
  + DateOfBirth : string
  + Doctors : Doctor[]
}

class Doctor {
  + IdNumber : int
  + Signature : string
}

class Treatment {
  + Stage : int
  + ConsentRequired : boolean
}

class Diagnosis {
  + PriorityScore : PriorityScore
  + TreatmentPlan : Treatment[]
}

class Hospital {
  + Name : string
  + Doctors : Doctor[]
  + Patients : Patient[]
}

Patient "1" -- "*" Doctor
Doctor "0..*" -- "1" Patient
Diagnosis "1" -- "*" Treatment
Hospital "1" -- "*" Diagnosis

@enduml

